raw:
{
  "candidates": [
    {
      "claimType": "preference",
      "statement": "该用户对特定手办系列具有深度收藏偏好，并倾向于通过优化展示空间来维持收藏体验。",
      "supportingRefs": [
        "o1",
        "o2",
        "o3"
      ],
      "alternativeExplanations": [
        "用户可能只是近期购买了少量高价值单品，而非长期偏好（尽管重复购买9次降低了此可能性）",
        "展示柜安装可能是为了整理杂物而非专门针对手办收藏"
      ],
      "verificationPlan": [
        {
          "op": "retrieveRelated",
          "question": "查询近6个月内购买的手办品牌/系列名称，验证是否集中在同一IP或系列"
        },
        {
          "op": "checkCoverage",
          "question": "检查展示柜安装前后，是否有其他非手办类大型物品入库记录，以排除通用整理用途"
        }
      ],
      "whatWouldChangeTheAnswer": "若购买记录显示系列分散且无关联，则“深度偏好”不成立；若展示柜用于存放书籍或杂物，则“维持收藏体验”的动机减弱。",
      "evidenceGrade": "支持",
      "action": "adopt"
    },
    {
      "claimType": "recurringBehavior",
      "statement": "该用户在收藏过程中存在定期清理冗余库存（重复款或品相差）的行为模式。",
      "supportingRefs": [
        "o4"
      ],
      "alternativeExplanations": [
        "出售行为仅为一次性回血手段，后续不再发生",
        "出售是因为资金周转需求，而非主动管理库存"
      ],
      "verificationPlan": [
        {
          "op": "comparePeriods",
          "question": "对比过去12个月内的二手出售记录，确认此类出售是偶发还是周期性出现"
        },
        {
          "op": "searchCounterEvidence",
          "question": "检查同期是否有大量购入新品的记录，以判断是单纯减持还是“进一出一”的置换行为"
        }
      ],
      "whatWouldChangeTheAnswer": "若未来半年内无类似出售记录，则该行为仅为偶发事件；若伴随大量新品购入，则更倾向于“置换/迭代”而非单纯清理。",
      "evidenceGrade": "线索",
      "action": "observe"
    }
  ]
}
